    81  static bool isTransmeridianCell(H3Index h) {
    82      CellBoundary bndry;
    83      H3_EXPORT(cellToBoundary)(h, &bndry);
    84
    85      double minLng = M_PI, maxLng = -M_PI;
    86      for (int i = 0; i < bndry.numVerts; i++) {
    87          if (bndry.verts[i].lng < minLng) minLng = bndry.verts[i].lng;
    88          if (bndry.verts[i].lng > maxLng) maxLng = bndry.verts[i].lng;
    89      }
    90
    91      return maxLng - minLng > M_PI - (M_PI / 4);
    92  }
